import { X } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button, buttonVariants } from "@/components/ui/button";
import { ButtonGroup, ButtonGroupText } from "@/components/ui/button-group";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

import { useIsMobile } from "@/hooks/use-mobile";
import { cn } from "@/lib/utils";
import FilterRenderer from "./filterRenderer";
import useMultiFilter from "./utils/useMultiFilter";
import { FilterState, FilterValues, Operation } from "./utils/Utils";

function SubMenuFilter({
  selectedOption,
  setSelectedOption,
  availableOptions,
}: {
  selectedOption: Operation | null;
  setSelectedOption: (option: Operation) => void;
  availableOptions: Operation[];
}) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);

  if (!selectedOption) return <></>;

  return (
    <DropdownMenu open={open} onOpenChange={setOpen}>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          data-slot="filter-operator"
          className="text-muted-foreground hover:text-foreground font-normal underline underline-offset-4 shadow-sm"
        >
          {t(selectedOption.label)}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent className="w-(--anchor-width) p-0" align="start">
        {availableOptions.map((option) => (
          <DropdownMenuItem
            key={option.value || option.label}
            onSelect={() => setSelectedOption(option)}
          >
            {t(option.label)}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export function SelectedFilterBar({
  selectedFilterKey,
  selectedFilters,
  onClick,
  clearFilter,
  openState,
  setOpenState,
  onFilterChange,
  onOperationChange,
  selectedBarClassName,
  selectedValueClassName,
  facilityId,
}: {
  selectedFilterKey: string;
  selectedFilters: Record<string, FilterState>;
  onClick: () => void;
  clearFilter: () => void;
  openState: boolean;
  setOpenState: (open: boolean) => void;
  onFilterChange: (filterKey: string, values: FilterValues) => void;
  onOperationChange: (filterKey: string, operation: string) => void;
  selectedBarClassName?: string;
  selectedValueClassName?: string;
  facilityId?: string;
}) {
  const { t } = useTranslation();
  const isMobile = useIsMobile();
  const { filter, selected, selectedOperation, availableOperations } =
    useMultiFilter(selectedFilterKey, selectedFilters);

  if (!selectedOperation) return <></>;

  const fieldButton = (
    <DropdownMenuTrigger asChild>
      <Button
        variant="outline"
        data-slot="filter-field"
        className="text-foreground [&_svg]:text-muted-foreground min-w-0 flex-1 justify-start font-medium md:flex-none"
        onClick={onClick}
      >
        {filter.icon}
        <span className="truncate">{t(filter.label)}</span>
      </Button>
    </DropdownMenuTrigger>
  );

  const operatorDropdown = (
    <SubMenuFilter
      selectedOption={selectedOperation}
      setSelectedOption={(operation) =>
        onOperationChange(filter.key, operation.value || operation.label)
      }
      availableOptions={availableOperations ?? []}
    />
  );

  const selectedValue = (
    <div className="flex min-w-0 flex-1 overflow-hidden">
      {filter.renderSelected?.(selected, filter, onFilterChange)}
    </div>
  );
  const valueClassName = cn(
    "min-w-0 flex-1 justify-start font-normal shadow-sm md:flex-none md:max-w-64 lg:max-w-80 xl:max-w-96",
    selectedValueClassName,
  );
  // These renderers own menu/tooltip triggers; keep their shell noninteractive.
  const valueOwnsTrigger =
    filter.type === "date" ||
    filter.type === "tag" ||
    filter.type === "activity_definition";
  const valueSelector = valueOwnsTrigger ? (
    <ButtonGroupText
      data-slot="filter-value"
      className={cn(buttonVariants({ variant: "outline" }), valueClassName)}
    >
      {selectedValue}
    </ButtonGroupText>
  ) : (
    <DropdownMenuTrigger asChild>
      <Button
        variant="outline"
        data-slot="filter-value"
        className={valueClassName}
        onClick={onClick}
      >
        {selectedValue}
      </Button>
    </DropdownMenuTrigger>
  );

  const removeButton = !filter.disableClear && (
    <Button
      variant="outline"
      data-slot="filter-remove"
      onClick={clearFilter}
      aria-label={t("remove_filter")}
      aria-description={t(filter.label)}
      size="icon"
      className="text-muted-foreground hover:text-foreground"
    >
      <X />
    </Button>
  );

  return (
    <DropdownMenu
      open={openState || false}
      onOpenChange={(isOpen) => setOpenState(isOpen)}
    >
      {isMobile ? (
        <div
          data-slot="filter-chip"
          role="group"
          aria-label={t(filter.label)}
          className={cn(
            "bg-muted-background flex w-full max-w-full min-w-0 flex-col rounded-lg p-1",
            selectedBarClassName,
          )}
        >
          <ButtonGroup className="grid w-full grid-cols-2 [&>*:not(:first-child)]:rounded-l-none! [&>*:not(:last-child)]:rounded-r-none! [&>*:not(:first-child)]:border-l-0! [&>*]:rounded-b-none! [&>*]:shadow-none! [&>[data-slot]:not(:has(~[data-slot]))]:rounded-br-none!">
            {fieldButton}
            {operatorDropdown}
          </ButtonGroup>
          <ButtonGroup className="w-full [&>*:not(:first-child)]:rounded-l-none! [&>*:not(:last-child)]:rounded-r-none! [&>*]:border-t-0! [&>*:not(:first-child)]:border-l-0! [&>*]:rounded-t-none! [&>*]:shadow-none! [&>[data-slot]:not(:has(~[data-slot]))]:rounded-tr-none!">
            {valueSelector}
            {removeButton}
          </ButtonGroup>
        </div>
      ) : (
        <ButtonGroup
          data-slot="filter-chip"
          aria-label={t(filter.label)}
          className={cn(
            "w-fit max-w-full min-w-0 shrink-0 [&>*:not(:first-child)]:rounded-l-none! [&>*:not(:last-child)]:rounded-r-none! [&>*:not(:first-child)]:border-l-0!",
            selectedBarClassName,
          )}
        >
          {fieldButton}
          {operatorDropdown}
          {valueSelector}
          {removeButton}
        </ButtonGroup>
      )}
      <DropdownMenuContent className="w-80 p-0" align="start">
        <FilterRenderer
          activeFilter={filter.key}
          selectedFilters={selectedFilters}
          onFilterChange={onFilterChange}
          facilityId={facilityId}
        />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
import { type VariantProps } from "class-variance-authority";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Badge, badgeVariants } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

import FilterHeader from "./filterHeader";
import useMultiFilterNavigationShortcuts from "./utils/useMultiFilterNavigationShortcuts";
import useMultiFilterSearch from "./utils/useMultiFilterSearch";
import {
  FilterConfig,
  FilterMode,
  FilterOption,
  FilterValues,
  getColorForOption,
} from "./utils/Utils";

export default function GenericFilter({
  filter,
  selectedValues = [],
  handleBack,
  onFilterChange,
  showColorIndicators = false,
}: {
  filter: FilterConfig;
  selectedValues?: string[];
  handleBack?: () => void;
  onFilterChange?: (filterKey: string, values: FilterValues) => void;
  showColorIndicators?: boolean;
}) {
  const { t } = useTranslation();
  const {
    search,
    setSearch,
    filteredItems: filteredOptions,
  } = useMultiFilterSearch(filter.options);

  const handleOptionToggle = (value: string, checked: boolean) => {
    if (!onFilterChange) return;

    if (checked) {
      onFilterChange(filter.key, [...selectedValues, value]);
    } else {
      onFilterChange(
        filter.key,
        selectedValues.filter((v) => v !== value),
      );
    }
  };

  const handleCheckboxToggle = (value: string, checked: boolean) => {
    if (!onFilterChange) return;
    if (checked) {
      onFilterChange(filter.key, [value]);
    } else {
      onFilterChange(filter.key, []);
    }
  };

  const { focusItemIndex, setFocusItemIndex } =
    useMultiFilterNavigationShortcuts(filteredOptions.length, handleBack);

  return (
    <div className="p-0">
      {handleBack && <FilterHeader label={filter.label} onBack={handleBack} />}
      <div className="p-3 border-b">
        <Input
          placeholder={t("search_options")}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          onKeyDown={(e) => e.stopPropagation()}
          className="h-8 text-base sm:text-sm"
        />
      </div>
      <div className="p-3 max-h-[30vh] overflow-y-auto">
        {filteredOptions.length === 0 ? (
          <div className="text-sm text-gray-500 text-center py-4">
            {t("no_results_found")}
          </div>
        ) : (
          <FilterOptionsList
            options={filteredOptions}
            selectedValues={selectedValues}
            onOptionToggle={
              filter.mode === "single"
                ? handleCheckboxToggle
                : handleOptionToggle
            }
            showColorIndicators={showColorIndicators}
            focusItemIndex={focusItemIndex}
            setFocusItemIndex={setFocusItemIndex}
            mode={filter.mode}
          />
        )}
      </div>
    </div>
  );
}

function FilterOptionsList({
  options,
  selectedValues,
  onOptionToggle,
  showColorIndicators,
  focusItemIndex,
  setFocusItemIndex,
  mode,
}: {
  options: FilterOption[];
  selectedValues: string[];
  onOptionToggle: (value: string, checked: boolean) => void;
  showColorIndicators?: boolean;
  focusItemIndex: number | null;
  setFocusItemIndex: (index: number) => void;
  mode?: FilterMode;
}) {
  const [focusItemRef, setFocusItemRef] = useState<HTMLDivElement | null>(null);

  useEffect(() => {
    if (focusItemRef) {
      focusItemRef.focus();
    }
  }, [focusItemRef]);

  return (
    <div className="flex flex-col gap-1">
      {options.map((option, index) => (
        <div
          key={option.value}
          className="flex items-center space-x-3 p-2 rounded-md hover:bg-gray-50 transition-colors cursor-pointer"
          ref={index === focusItemIndex ? setFocusItemRef : null}
          onFocus={() => setFocusItemIndex(index)}
          tabIndex={index}
          onClick={() => {
            onOptionToggle(
              option.value,
              !selectedValues.includes(option.value),
            );
          }}
          onKeyDown={(e) => {
            if (e.key === " " || e.key === "Enter") {
              e.preventDefault();
              onOptionToggle(
                option.value,
                !selectedValues.includes(option.value),
              );
            }
          }}
        >
          {mode === "single" ? (
            <RadioGroup
              id={`${option.value}-${index}`}
              value={selectedValues.length > 0 ? selectedValues[0] : ""}
              onValueChange={() => {}}
              className="pointer-events-none"
              onClick={(e) => e.stopPropagation()}
            >
              <RadioGroupItem value={option.value} />
            </RadioGroup>
          ) : (
            <Checkbox
              checked={selectedValues.includes(option.value)}
              className="h-4 w-4 text-blue-600 border-gray-300 focus:ring-blue-500 pointer-events-none"
            />
          )}
          {showColorIndicators && (
            <div
              className={cn(
                "h-3 w-3 rounded-full shrink-0 border",
                option.color || getColorForOption(index),
              )}
            />
          )}
          <span className="text-sm text-gray-700 flex-1">{option.label}</span>
        </div>
      ))}
    </div>
  );
}

export const GenericSelectedBadge = ({
  selectedValue,
  selectedLength,
  className,
  variant,
}: {
  selectedValue: string;
  selectedLength: number;
  className?: string;
  variant?: VariantProps<typeof badgeVariants>["variant"];
}) => {
  const { t } = useTranslation();
  return (
    <div className="flex min-w-0 flex-1 items-center gap-1 overflow-hidden">
      <Badge
        variant={variant || "outline"}
        className={cn(
          "min-w-0 max-w-full overflow-hidden rounded-sm",
          className,
        )}
      >
        <span className="block min-w-0 truncate whitespace-nowrap">
          {t(selectedValue)}
        </span>
      </Badge>
      {selectedLength > 1 && (
        <Badge variant="neutral" size="sm" counter className="shrink-0">
          +{selectedLength - 1}
        </Badge>
      )}
    </div>
  );
};
import { format, isBefore, isSameDay, isValid } from "date-fns";
import { ChevronRight } from "lucide-react";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Input } from "@/components/ui/input";
import { Separator } from "@/components/ui/separator";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import FilterHeader from "./filterHeader";
import NavigationHelper from "./utils/navigation-helper";
import useMultiFilterNavigationShortcuts from "./utils/useMultiFilterNavigationShortcuts";
import {
  DateFilterMeta,
  DateRangeOption,
  FilterConfig,
  FilterDateRange,
  FilterValues,
  isSameDateRange,
  longDateRangeOptions,
} from "./utils/Utils";

function CustomDateRange({
  dateFrom,
  dateTo,
  setDateFrom,
  setDateTo,
  handleDateChange,
  onFilterChange,
  filter,
  setView,
}: {
  dateFrom: Date | undefined;
  dateTo: Date | undefined;
  setDateFrom: (date: Date | undefined) => void;
  setDateTo: (date: Date | undefined) => void;
  handleDateChange: (date: { from?: Date; to?: Date }) => void;
  onFilterChange: (filterKey: string, values: FilterValues) => void;
  filter: FilterConfig;
  setView: (view: "options" | "custom") => void;
}) {
  const { t } = useTranslation();
  return (
    <>
      <FilterHeader
        label={t("custom_date_range")}
        onBack={() => setView("options")}
      />
      <div className="w-full flex flex-col max-h-[30vh] overflow-y-auto">
        <Calendar
          mode="range"
          selected={{ from: dateFrom, to: dateTo }}
          onSelect={(range, triggerDate) =>
            handleDateChange(range ?? { from: triggerDate, to: undefined })
          }
          styles={{
            day: {
              width: "40px",
            },
            weekdays: {
              width: "100%",
              justifyContent: "space-between",
            },
            nav: {
              display: "flex",
              flexDirection: "row",
              justifyContent: "space-between",
              padding: "0.5rem",
            },
          }}
          className="w-full"
          captionLayout="dropdown"
          endMonth={new Date(2100, 11, 31)}
          monthCaptionClassName="self-center"
          rangeMiddleClassName="bg-primary/10 [&>button]:rounded-md"
        />
        <div className="my-2">
          <Separator orientation="horizontal" className="bg-gray-200 h-px" />
        </div>
        <div className="flex flex-col gap-2 p-3 pt-0">
          <div>
            <label className="text-sm text-gray-600 mb-1 block capitalize">
              {t("from")}
            </label>
            <Input
              type="date"
              value={dateFrom ? format(dateFrom, "yyyy-MM-dd") : ""}
              onChange={(e) => {
                if (e.target.value) {
                  setDateFrom(new Date(e.target.value));
                } else {
                  setDateFrom(undefined);
                }
              }}
              placeholder={t("start_date")}
              className="flex flex-col justify-between text-sm"
            />
          </div>
          <div>
            <label className="text-sm text-gray-600 mb-1 block capitalize">
              {t("to")}
            </label>
            <Input
              type="date"
              value={dateTo ? format(dateTo, "yyyy-MM-dd") : ""}
              onChange={(e) => {
                if (e.target.value) {
                  setDateTo(new Date(e.target.value));
                } else {
                  setDateTo(undefined);
                }
              }}
              placeholder={t("end_date")}
              className="flex flex-col justify-between text-sm"
            />
          </div>
        </div>
      </div>
      <div className="px-3 p-2">
        <Button
          variant="primary"
          className="w-full justify-center"
          onClick={() => {
            if (dateFrom && dateTo) {
              onFilterChange(filter.key, { from: dateFrom, to: dateTo });
              setView("options");
            } else if (dateFrom) {
              onFilterChange(filter.key, { from: dateFrom, to: undefined });
              setView("options");
            } else if (dateTo) {
              onFilterChange(filter.key, { from: undefined, to: dateTo });
              setView("options");
            }
          }}
          disabled={
            (!dateFrom && !dateTo) ||
            (dateFrom && dateTo && isBefore(dateTo, dateFrom))
          }
        >
          {t("confirm")}
        </Button>
      </div>
    </>
  );
}

function DateRangeOptions({
  options,
  handleBack,
  setView,
  isCustomDateRangeSelected,
  filter,
  handleDateRangeSelect,
  isSameRange,
}: {
  options: DateRangeOption[];
  handleBack?: () => void;
  setView: (view: "options" | "custom") => void;
  isCustomDateRangeSelected: boolean;
  filter: FilterConfig;
  handleDateRangeSelect: (option: DateRangeOption) => void;
  isSameRange: (option: DateRangeOption) => boolean;
}) {
  const { t } = useTranslation();
  const [focusItemRef, setFocusItemRef] = useState<HTMLDivElement | null>(null);
  const { focusItemIndex, setFocusItemIndex } =
    useMultiFilterNavigationShortcuts(options.length + 1, handleBack);

  useEffect(() => {
    if (focusItemRef) {
      focusItemRef.focus();
    }
  }, [focusItemRef]);

  return (
    <>
      {handleBack && <FilterHeader label={filter.label} onBack={handleBack} />}
      <div className="flex flex-col gap-1 p-2 max-h-[30vh] overflow-y-auto">
        {options.map((option, index) => (
          <DropdownMenuItem
            key={index}
            ref={index === focusItemIndex ? setFocusItemRef : null}
            onFocus={() => setFocusItemIndex(index)}
            onSelect={(e) => {
              e.preventDefault();
              handleDateRangeSelect(option);
            }}
            className={cn(
              "w-full justify-start px-3 font-medium text-sm text-gray-950",
              isSameRange(option) && "bg-gray-100 border-green-500 border",
            )}
          >
            {option.count
              ? t(option.label, { count: option.count })
              : t(option.label)}
          </DropdownMenuItem>
        ))}
        <DropdownMenuItem
          ref={options.length === focusItemIndex ? setFocusItemRef : null}
          className={cn(
            "w-full justify-between px-3 font-medium text-sm text-gray-950",
            isCustomDateRangeSelected && "bg-gray-100 border-green-500 border",
          )}
          onSelect={(e) => {
            e.preventDefault();
            setView("custom");
          }}
          onFocus={() => setFocusItemIndex(options.length)}
        >
          {t("custom_date_range")}
          <ChevronRight className="h-4 w-4" />
        </DropdownMenuItem>
      </div>
      <NavigationHelper isActiveFilter={true} />
    </>
  );
}

export default function RenderDateFilter({
  filter,
  selected,
  onFilterChange,
  handleBack,
  defaultView,
}: {
  filter: FilterConfig;
  selected: FilterDateRange;
  onFilterChange: (filterKey: string, values: FilterValues) => void;
  handleBack?: () => void;
  defaultView?: "options" | "custom";
}) {
  const [dateFrom, setDateFrom] = useState<Date | undefined>(selected?.from);
  const [dateTo, setDateTo] = useState<Date | undefined>(selected?.to);
  const [view, setView] = useState<"options" | "custom">(
    defaultView || "options",
  );
  const options =
    (filter.meta as DateFilterMeta)?.presetOptions || longDateRangeOptions;

  const handleDateRangeSelect = (option: DateRangeOption) => {
    const { from, to } = option.getDateRange();
    setDateFrom(from);
    setDateTo(to);
    onFilterChange(filter.key, { from, to });
  };

  const handleDateChange = (date: { from?: Date; to?: Date }) => {
    setDateFrom(date?.from);
    setDateTo(date?.to);
  };

  const isSameRange = (option: DateRangeOption) =>
    isSameDateRange({ from: dateFrom, to: dateTo }, option.getDateRange());

  const isCustomDateRangeSelected =
    selected.from || selected.to
      ? !options.some((option) => isSameRange(option))
      : false;

  useEffect(() => {
    setDateFrom(selected.from);
    setDateTo(selected.to);
  }, [selected]);

  return (
    <div className="pt-0">
      {view == "custom" ? (
        <CustomDateRange
          dateFrom={dateFrom}
          dateTo={dateTo}
          setDateFrom={setDateFrom}
          setDateTo={setDateTo}
          handleDateChange={handleDateChange}
          onFilterChange={onFilterChange}
          filter={filter}
          setView={setView}
        />
      ) : (
        <DateRangeOptions
          options={options}
          handleBack={handleBack}
          setView={setView}
          isCustomDateRangeSelected={isCustomDateRangeSelected}
          filter={filter}
          handleDateRangeSelect={handleDateRangeSelect}
          isSameRange={isSameRange}
        />
      )}
    </div>
  );
}

export const getDateOperations = (selected: FilterDateRange) => {
  if (selected.from && selected.to) {
    if (isSameDay(selected.from, selected.to)) {
      return [{ label: "is_on" }];
    } else {
      return [{ label: "b/w" }];
    }
  } else if (selected.from) {
    return [{ label: "after" }];
  } else if (selected.to) {
    return [{ label: "before" }];
  }
  return [];
};
export const SelectedDateBadge = ({
  selected,
  filter,
  onFilterChange,
}: {
  selected: FilterDateRange;
  filter: FilterConfig;
  onFilterChange: (filterKey: string, values: FilterValues) => void;
}) => {
  const { t } = useTranslation();
  const hasValidFrom = !!selected.from && isValid(selected.from);
  const hasValidTo = !!selected.to && isValid(selected.to);
  if (!hasValidFrom && !hasValidTo) return <></>;
  const isSameDate =
    selected.from && selected.to && isSameDay(selected.from, selected.to);
  const presentDate = isSameDate ? selected.from : selected.from || selected.to;

  const isSameRange = (option: DateRangeOption) =>
    isSameDateRange(selected, option.getDateRange());

  const isRangeSelected = (filter.meta as DateFilterMeta)?.presetOptions?.find(
    (option) => isSameRange(option),
  );

  const selectedDateLabel = isRangeSelected
    ? t(isRangeSelected.label, { count: isRangeSelected?.count })
    : selected.from && selected.to && !isSameDate
      ? (() => {
          const needsYear =
            selected.from.getFullYear() !== selected.to.getFullYear();
          return [selected.from, selected.to]
            .map((date) => format(date, needsYear ? "d MMM yy" : "d MMM"))
            .join(" - ");
        })()
      : presentDate
        ? format(presentDate, "d MMM yyyy")
        : "";

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          type="button"
          variant="ghost"
          className="h-auto min-w-0 flex-1 justify-start rounded-none border-0 p-0 font-normal shadow-none hover:bg-transparent focus-visible:outline-offset-0"
        >
          <span className="block min-w-0 truncate whitespace-nowrap">
            {selectedDateLabel}
          </span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" sideOffset={15} className="w-80 p-0">
        <RenderDateFilter
          filter={filter}
          selected={selected}
          onFilterChange={onFilterChange}
          defaultView="custom"
        />
      </DropdownMenuContent>
    </DropdownMenu>
  );
};
