import { test } from "@playwright/test";
import { ensureEnableWhenQuestionnaire } from "tests/support/questionnaireId";

test.use({ storageState: "tests/.auth/user.json" });

/**
 * Seeds the legacy enable-when fill-flow fixture questionnaire.
 *
 * The seeding itself lives in `tests/support/questionnaireId.ts` so the
 * specs can fall back to it in-process — see
 * `ensureEnableWhenQuestionnaire`'s own doc comment.
 */
test("ensure enable-when questionnaire exists", async () => {
  await ensureEnableWhenQuestionnaire();
});
import { faker } from "@faker-js/faker";
import { test } from "@playwright/test";
import fs from "fs";
import path from "path";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

test.use({ storageState: "tests/.auth/user.json" });

test("navigate to an patient - create and save account id", async ({
  page,
}) => {
  const facilityId = getFacilityId();
  const patientId = getPatientId();

  // Navigate to patient page
  await page.goto(
    `facility/${facilityId}/patient/${patientId}/accounts?status=active`,
  );

  try {
    await page.waitForLoadState("networkidle");

    // Check if an account already exists
    const goToAccountButton = page.getByRole("button", {
      name: "Go to account",
    });
    const accountExists = await goToAccountButton
      .isVisible()
      .catch(() => false);

    if (accountExists) {
      await goToAccountButton.click();
    } else {
      // Create new account
      await page.getByRole("button", { name: "Create Account" }).click();

      // Generate random account name using faker
      const accountName = faker.finance.accountName();

      await page
        .getByRole("textbox", { name: "Name *" })
        .pressSequentially(accountName);
      await page.getByRole("button", { name: "Create" }).click();

      await page.getByRole("button", { name: "Go to account" }).click();
    }

    // Wait for navigation and extract account ID from URL
    await page.waitForURL(/\/account\/[a-f0-9-]+/);
    const accountId = page.url().match(/\/account\/([a-f0-9-]+)/)?.[1];

    if (!accountId) {
      throw new Error("Failed to extract account ID from URL");
    }

    // Save account ID to meta file
    const metaPath = path.resolve("tests/.auth/accountMeta.json");
    fs.writeFileSync(metaPath, JSON.stringify({ id: accountId }, null, 2));
    console.log(`✅ Account created and saved: ${accountId}`);
  } catch (error) {
    console.error("❌ Failed to set up account:", error);
    throw error;
  }
});

import { test } from "@playwright/test";
import { format, subDays } from "date-fns";
import fs from "fs";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

test("navigate to an encounter and save patient and encounter id", async ({
  page,
}) => {
  const facilityId = getFacilityId();
  const createdDateAfter = format(subDays(new Date(), 90), "yyyy-MM-dd");
  const createdDateBefore = format(new Date(), "yyyy-MM-dd");
  // Pin to writable encounters (planned or in_progress); without a status
  // filter the list is -modified_date ordered and can hand back a discharged
  // or completed encounter where questionnaires are locked.
  await page.goto(
    `/facility/${facilityId}/encounters/patients/all?created_date_after=${createdDateAfter}&created_date_before=${createdDateBefore}&status=planned,in_progress`,
  );

  try {
    // Wait for encounter link to be visible
    await page.getByRole("link", { name: "View Encounter" }).first().click();

    // Wait for navigation to the encounter page
    await page.waitForURL(
