    await dialog.getByRole("option", { name: "Bio-Chemistry Lab" }).click();
    await expect(dialog).not.toBeVisible();
    await toggle.hover();
    await expect(
      page
        .getByRole("button", { name: "Bio-Chemistry Lab", exact: true })
        .and(page.locator('[aria-haspopup="dialog"]')),
    ).toBeVisible();
  });
});

