      handleCompatibleOpenChange(open, eventDetails);
    },
    [modal, handleCompatibleOpenChange],
  );

  return (
    <OverlayEventsContext.Provider value={handlersRef}>
      <SheetRootContext.Provider
        value={React.useMemo(
          () => ({ dismissibleRef, triggerShakeRef, modal }),
