  await page.getByRole("option", { name: "Pharmacy" }).click();
  await page
    .getByRole("combobox")
    .filter({ hasText: "Select locations" })
    .click();
  await page.getByPlaceholder("Search locations...").fill("Pharmacy");
  await page
    .getByRole("dialog")
    .getByRole("button")
    .filter({ hasText: /^$/ })
