// ---------------------------------------------------------------------------
// Direction compat shim (vaul "bottom"/"top" → Base UI "down"/"up")
// ---------------------------------------------------------------------------
function mapDirection(dir: string): "up" | "down" | "left" | "right" {
  const map: Record<string, "up" | "down" | "left" | "right"> = {
    bottom: "down",
    top: "up",
    left: "left",
    right: "right",
  };
  return (map[dir] ?? dir) as "up" | "down" | "left" | "right";
}

// ---------------------------------------------------------------------------
