            <span>{t("encounter_workspace_load_error")}</span>
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={() => {
                defaults.refetch();
                list.refetch();
              }}
            >
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}
      {parsed && (parsed.invalid || parsed.unsupportedVersion) && (
        <Alert>
          <AlertDescription>
            {t(
              parsed.unsupportedVersion
                ? "encounter_workspace_schema_unsupported"
                : "encounter_workspace_invalid",
            )}
          </AlertDescription>
        </Alert>
      )}
      {isLoadingSelection ? (
        <Skeleton className="h-64 w-full" />
      ) : firstVisibleTab ? (
        <EncounterNavigation
          tabs={tabs}
          currentTab={activeTab}
          onTabChange={(tab) => navigateToTab(tab)}
        />
      ) : (
        <Alert>
          <AlertDescription>
            {t("encounter_workspace_no_pages")}
          </AlertDescription>
        </Alert>
      )}
    </div>
  );
}
}

// Kept for backwards compat — Base UI handles nesting automatically.
const DrawerNestedRoot = Drawer;

// ---------------------------------------------------------------------------
// DrawerTrigger
// ---------------------------------------------------------------------------
function DrawerTrigger({
  asChild,
  render,
  children,
  ...props
}: Omit<DrawerPrimitive.Trigger.Props, "render"> & {
  asChild?: boolean;
  render?: RenderProp;
}) {
  const resolved = resolveAsChild(asChild, children, render);
  return (
    <DrawerPrimitive.Trigger
      data-slot="drawer-trigger"
      render={resolved.render}
      nativeButton={resolved.nativeButton}
      {...props}
    >
      {resolved.children}
    </DrawerPrimitive.Trigger>
  );
}

// ---------------------------------------------------------------------------
// DrawerPortal
// ---------------------------------------------------------------------------
function DrawerPortal({ ...props }: DrawerPrimitive.Portal.Props) {
  return <DrawerPrimitive.Portal data-slot="drawer-portal" {...props} />;
}

// ---------------------------------------------------------------------------
