const FillWorkspaceContext = createContext(false);

interface FillWorkspaceProviderProps {
  children: ReactNode;
  active: boolean;
}

/** Authenticated forms share the app frame; public and embedded forms own theirs. */
export function FillWorkspaceProvider({
  children,
  active,
}: FillWorkspaceProviderProps) {
  return (
    <FillWorkspaceContext.Provider value={active}>
      {children}
    </FillWorkspaceContext.Provider>
  );
}

export function useFillWorkspace() {
  return useContext(FillWorkspaceContext);
}

