        name: "Toggle Sidebar",
        exact: true,
      });
      await expect(toggle).toBeVisible();
      const sidebarState = page.locator("[data-app-sidebar-pinned]");
      const sidebar = page.locator('[data-sidebar="sidebar"]');
      if (
