      ) {
        await toggle.click();
      }
      await expect(sidebarState).toHaveAttribute(
        "data-app-sidebar-pinned",
        "true",
      );
      await expect(toggle).toHaveAttribute("aria-expanded", "true");
      await toggle.click();
      await page.mouse.move(900, 700);
